    void VerifyPreviewCache(){
        var image=preview.Source;for(int i=0;i<100;i++)Reload();if(!object.ReferenceEquals(image,preview.Source))throw new Exception("Unchanged settings must reuse the frozen notification preview");
        var original=owner.Configuration;var c=original.Copy();c.Notifications.Volume=(c.Notifications.Volume+5)%101;c.Notifications.Bounds.X+=10;owner.ApplyConfiguration(c);Reload();if(!object.ReferenceEquals(image,preview.Source))throw new Exception("Volume and position must not regenerate preview pixels");
        c.Notifications.Color="#654321";owner.ApplyConfiguration(c);Reload();if(object.ReferenceEquals(image,preview.Source))throw new Exception("Visual settings must refresh the preview");owner.ApplyConfiguration(original);Reload();
